<script>
  import { toTitle } from '@splendidlabz/utils'
  import { randomString } from '@splendidlabz/utils/dom'
  import { init } from '../../utils'
  import Icon from '../Icon/Icon.svelte'
  import FieldMeta from './FieldMeta.svelte'
  import HiddenInput from './HiddenInput.svelte'

  let {
    name: nameProp = '',
    items = $bindable([]),
    options = $bindable([]),
    selected = $bindable(null),
    ref = $bindable(null),
    class: klass = '',
    icon = null,
    iconClass = null,
    label = '',
    labelClass,
    labelVisible = true,
    hint = null,
    hintClass,
    error = null,
    errorClass,
    fieldClass = null,
    id = randomString(8),
    required = null,
    readonly = null,
    disabled = null,
    multiple = null,
    size = 0,
    onchange = null,
    ...rest
  } = $props()

  const isSingle = $derived(!multiple)
  // IDs for aria-describedby
  const hintId = $derived(hint ? id + '-hint' : '')
  const errorId = $derived(id + '-error')
  const describedBy = $derived(`${hintId} ${errorId}`.trim() || null)

  let name = $state('')

  init(() => {
    name = nameProp

    if (!options.length && !items.length) {
      console.error(
        'Select requires either `options` or `items` to be passed in.',
      )
    }

    // Fixes multiple name and selected values
    if (multiple) {
      if (!name.endsWith('[]')) name += '[]'
      if (!Array.isArray(selected)) selected = []
    }

    // Normalize items
    if (options.length) items = options
    items = items.map(option => {
      if (typeof option === 'string') option = { value: option }
      if (!option.label) option.label = toTitle(option.value)

      if (isSingle) {
        if (option.selected) selected = option.value
        if (option.value === selected) option.selected = true
        else option.selected = false
      } else {
        if (option.selected && !selected.includes(option.value))
          selected.push(option.value)
        if (selected.includes(option.value)) option.selected = true
        else option.selected = false
      }

      return option
    })

    // Preselect first item that is not disabled. (Single only)
    setSelected: if (!multiple && !selected) {
      const firstNotDisabled = items.findIndex(item => !item.disabled)
      if (firstNotDisabled === -1) break setSelected
      const s = items[firstNotDisabled] || items[0]
      s.selected = true
      selected = s.value
    }
  })

  // Properties for the select element
  const properties = $derived({
    ...rest,
    id,
    name,
    class: 'input ' + fieldClass,
    disabled: disabled || readonly,
    'aria-describedby': describedBy,
    'aria-invalid': error ? true : null,
    'aria-label': !labelVisible && label ? label : null,
    onchange: handleChange,
    required,
    size,
  })

  function handleChange() {
    items.forEach(item => {
      if (item.value === selected) item.selected = true
      else item.selected = false
    })
    if (onchange) onchange()
  }
</script>

{#snippet select()}
  <select {...properties} bind:this={ref} bind:value={selected}>
    {#each items as option (option.value)}
      {@const { label: optionLabel, value, ...optionRest } = option}
      <option {...optionRest} {value}>{optionLabel}</option>
    {/each}
  </select>
{/snippet}

<!-- Svelte requires multiple to be passed as a standard attribute for it to bind to an array value, hence the duplication here -->
{#snippet multiselect()}
  <select {...properties} bind:this={ref} multiple bind:value={selected}>
    {#each items as option (option.value)}
      {@const { label: optionLabel, value, ...optionRest } = option}
      <option {...optionRest} {value}>{optionLabel}</option>
    {/each}
  </select>
{/snippet}

{#snippet selectIcon()}
  {#if icon}
    <Icon class={iconClass} {icon} />
  {:else}
    <svg class={iconClass} height="24" viewBox="0 0 24 24" width="24">
      <path
        d="M8 9L12 5L16 9M16 15L12 19L8 15"
        stroke="currentcolor"
        stroke-linecap="round"
        stroke-linejoin="round"
        stroke-width="2"
      />
    </svg>
  {/if}
{/snippet}

<div class="input-container select {klass}">
  <FieldMeta
    {id}
    {error}
    {errorClass}
    {hint}
    {hintClass}
    {label}
    {labelClass}
    {labelVisible}
  />

  <div class="input-group items-center stack" class:disabled class:readonly>
    <!-- Single Select -->
    {#if isSingle}
      {@render select()}
      {#if readonly}
        <HiddenInput {name} value={selected} />
      {/if}

      <div class="pos-right pointer-events-none z-[3]">
        {@render selectIcon()}
      </div>
    {/if}

    <!-- Multi Select -->
    {#if multiple}
      {@render multiselect()}
      {#if readonly}
        {#each selected as item (item)}
          <HiddenInput {name} value={item} />
        {/each}
      {/if}
    {/if}
  </div>
</div>
